<?php $formatBytes=static function(int$bytes):string{if($bytes>=1073741824)return number_format($bytes/1073741824,2).' GB';if($bytes>=1048576)return number_format($bytes/1048576,2).' MB';if($bytes>=1024)return number_format($bytes/1024,1).' KB';return$bytes.' B';}; ?>
<section><div class="page-heading"><div><p class="eyebrow">Operations</p><h1>System status</h1><p class="muted">Read-only health information. No credentials, environment values, stack traces, or raw error messages are displayed.</p></div></div><div class="status-grid"><article class="panel"><span class="status-indicator <?= $status['database']['ok']?'ok':'bad' ?>"></span><h2>Database</h2><strong><?= e($status['database']['message']) ?></strong><small><?= e($status['migrations']['count']) ?> migrations · Latest <?= e($status['migrations']['latest']??'none') ?></small></article><article class="panel"><span class="status-indicator <?= $status['https']?'ok':'warn' ?>"></span><h2>Runtime</h2><strong>PHP <?= e($status['runtime']['php_version']) ?></strong><small><?= e($status['runtime']['environment']) ?> · HTTPS <?= $status['https']?'detected':'not detected' ?></small></article><article class="panel"><span class="status-indicator <?= array_product(array_map('intval',$status['writable']))?'ok':'bad' ?>"></span><h2>Writable paths</h2><strong><?= array_sum(array_map('intval',$status['writable'])) ?>/<?= count($status['writable']) ?> ready</strong><small>Logs, sessions, rate limits, uploads</small></article><article class="panel"><span class="status-indicator <?= $status['error_log']['exists']?'warn':'ok' ?>"></span><h2>Error log</h2><strong><?= $status['error_log']['exists']?'Log present':'No log file' ?></strong><small><?= e($formatBytes($status['error_log']['bytes'])) ?> · Updated <?= e($status['error_log']['updated_at']??'never') ?></small></article></div><div class="admin-split"><section class="panel"><div class="panel-title"><h2>Storage usage</h2><span>Application-owned directories</span></div><div class="storage-list"><?php foreach(['uploads'=>'Uploaded assets','logs'=>'Logs','sessions'=>'Sessions','cache'=>'Cache']as$key=>$label):?><div><span><?= e($label) ?></span><strong><?= e($formatBytes($status['storage'][$key]['bytes'])) ?></strong><small><?= e($status['storage'][$key]['files']) ?> files</small></div><?php endforeach ?></div></section><section class="panel"><div class="panel-title"><h2>Permissions</h2><span>Required writable paths</span></div><div class="permission-list"><?php foreach($status['writable']as$key=>$writable):?><div><span><?= e(ucwords(str_replace('_',' ',$key))) ?></span><strong class="<?= $writable?'good':'bad-text' ?>"><?= $writable?'Writable':'Not writable' ?></strong></div><?php endforeach ?></div></section></div><section class="panel"><div class="panel-title"><h2>Scheduled tasks and backups</h2><span>Recorded heartbeats</span></div><div class="task-grid"><?php foreach($status['tasks']as$task):?><?php $stale=$task['task_key']==='subscription_lifecycle'&&$task['last_completed_at']&&strtotime($task['last_completed_at'])<time()-900;?><article><div><strong><?= e($task['label']) ?></strong><span class="badge <?= strtolower($stale?'FAILED':$task['last_status']) ?>"><?= $stale?'STALE':e($task['last_status']) ?></span></div><dl><dt>Last started</dt><dd><?= e($task['last_started_at']??'Never') ?></dd><dt>Last completed</dt><dd><?= e($task['last_completed_at']??'Never') ?></dd></dl><?php if($task['task_key']==='subscription_lifecycle'&&$task['last_status']==='NEVER'):?><p>Configure the lifecycle cron after deployment.</p><?php elseif(str_starts_with($task['task_key'],'backup_')&&$task['last_status']==='NEVER'):?><p>No verified backup run has been recorded.</p><?php endif ?></article><?php endforeach ?></div><p class="admin-footnote">Backup rows report external job heartbeats; they do not claim that an unverified backup exists.</p></section></section>
